-- Generated by npm run db:diff -- messages_status_counters.
-- Excludes pre-existing Business Hours/lifecycle drift and known grant-revoke noise.
CREATE OR REPLACE FUNCTION public.get_conversation_queue_counts(p_organization_id uuid, p_routing_queue_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(key text, count bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  request_role public.role;
  current_agent_id uuid;
begin
  if auth.uid() is null or not exists (
    select 1 from public.get_authorized_orgs('agent') a(id)
    where a.id = p_organization_id
  ) then
    raise exception 'organization is not accessible to the authenticated user' using errcode = '42501';
  end if;
  request_role := public.get_request_organization_role(p_organization_id);
  current_agent_id := public.get_current_human_agent_id(p_organization_id);
  if p_routing_queue_id is not null and not exists (
    select 1 from public.routing_queues q
    where q.organization_id = p_organization_id and q.id = p_routing_queue_id
      and (request_role <> 'agent'::public.role or exists (
        select 1 from public.routing_queue_members m
        where m.organization_id = q.organization_id and m.routing_queue_id = q.id
          and m.agent_id = current_agent_id
      ))
  ) then
    raise exception 'routing queue is not accessible to the authenticated user' using errcode = '42501';
  end if;

  return query
  with eligible as materialized (
    select c.id, c.status, c.assigned_agent_id, c.routing_queue_id,
      exists (
        select 1 from public.message_mentions mention
        join public.messages message on message.organization_id = mention.organization_id
          and message.id = mention.message_id
        where mention.organization_id = c.organization_id and message.conversation_id = c.id
          and mention.mentioned_agent_id = current_agent_id
      ) as mentioned,
      (select max(m.timestamp) from public.messages m
        where m.organization_id = c.organization_id and m.conversation_id = c.id
          and m.direction = 'incoming'::public.direction) as latest_incoming_at
    from public.conversations c
    where c.organization_id = p_organization_id
      and public.is_support_inbox_visible(c.organization_id, c.id)
  )
  select q.key, count(e.id)
  from public.get_conversation_queues(p_organization_id) q
  left join eligible e on (
    (q.key = 'mentioned' or p_routing_queue_id is null or e.routing_queue_id = p_routing_queue_id)
    and case q.key
      when 'all_active' then e.status = 'active'
      when 'assigned' then e.status = 'active' and e.assigned_agent_id is not null
        and (request_role <> 'agent'::public.role or e.assigned_agent_id = current_agent_id)
      when 'pending' then e.status = 'active' and e.assigned_agent_id is null
      when 'mentioned' then e.mentioned
      when 'spam' then e.status = 'spam'
        and (request_role <> 'agent'::public.role or e.assigned_agent_id = current_agent_id)
      when 'closed' then e.status = 'closed'
        and (request_role <> 'agent'::public.role or e.assigned_agent_id = current_agent_id)
      when 'expired' then e.status = 'active' and e.latest_incoming_at <= now() - interval '24 hours'
        and (request_role <> 'agent'::public.role or e.assigned_agent_id is null or e.assigned_agent_id = current_agent_id)
      else false
    end
  )
  where q.enabled
  group by q.key, q."order"
  order by q."order";
end;
$function$
;

revoke all on function public.get_conversation_queue_counts(uuid,uuid) from public, anon;
grant execute on function public.get_conversation_queue_counts(uuid,uuid) to authenticated;


